export const getDefaultSecondaryLanguage = (primary: UiLanguage): UiLanguage =>
  primary === 'en-us' || primary === 'en-uk' ? 'chs' : 'en-us';

export const isUiLanguage = (value: unknown): value is UiLanguage =>
  value === 'chs' || value === 'cht' || value === 'en-us' || value === 'en-uk' || value === 'jpn';

export const detectDefaultUiLanguage = (): UiLanguage => {
  if (typeof navigator === 'undefined') return 'en-us';
  const candidates = Array.isArray(navigator.languages) ? navigator.languages : [];
  const fallback = navigator.language ? [navigator.language] : [];
  const languages = [...candidates, ...fallback].filter(Boolean);
  for (const raw of languages) {
    const language = String(raw).toLowerCase();
    if (language.startsWith('zh')) {
      if (language.includes('hant') || language.includes('tw') || language.includes('hk') || language.includes('mo')) {
        return 'cht';
      }
      return 'chs';
    }
    if (language.startsWith('ja')) return 'jpn';
    if (language.startsWith('en')) {
      if (language.includes('gb') || language.includes('uk')) return 'en-uk';
      return 'en-us';
    }
  }
  return 'en-us';
};

